import{d as S,C as l,o as A,c as C,a3 as s,E as e,j as t,a}from"./chunks/framework.Q4yG9rk_.js";const N=JSON.parse('{"title":"庄子·庚桑楚","description":"从庚桑楚居畏垒而不受尊奉，到南荣趎问道与老聃论卫生之经，理解名贤、思虑、教化限度与保全生命之间的关系。","frontmatter":{"title":"庄子·庚桑楚","description":"从庚桑楚居畏垒而不受尊奉，到南荣趎问道与老聃论卫生之经，理解名贤、思虑、教化限度与保全生命之间的关系。","category":"guide","aliases":["庚桑楚","庄子庚桑楚","zhuangzi chapter 23"],"source":["《庄子》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-23.md","filePath":"daoism/zhuang-zi/chapter-23.md","lastUpdated":1792641266000}'),I={name:"daoism/zhuang-zi/chapter-23.md"},R=S({...I,setup(V){const g=[{id:"gsc_weilei_s1",label:"老聃之役：庚桑楚居畏垒",sentences:[["老聃之役有庚桑楚者，",{text:"偏得",glossary:"gsc_weilei_piande"},"老聃之道，以北居畏垒之山。"],["其臣之",{text:"画然知者",glossary:"gsc_weilei_huaran"},"去之，其妾之",{text:"挈然仁者",glossary:"gsc_weilei_qieran"},"远之。"],[{text:"拥肿之与居，鞅掌之为使",glossary:"gsc_weilei_yongzhong"},"。居三年，",{text:"畏垒大壤",glossary:"gsc_weilei_rang"},"。"]]},{id:"gsc_weilei_s2",label:"日计不足，岁计有余：民欲祭祀",sentences:[["畏垒之民相与言曰：「庚桑子之始来，吾洒然异之。"],["今吾日计之而不足，岁计之而有余。庶几其圣人乎！"],["子胡不相与",{text:"尸而祝之，社而稷之",glossary:"gsc_weilei_shizhu"},"乎？」"],["庚桑子闻之，南面而不释然。弟子异之。"]]},{id:"gsc_weilei_s3",label:"春秋生成：天道已行",sentences:[["庚桑子曰：「弟子何异于予？夫春气发而百草生，正得秋而万宝成。"],["夫春与秋，岂无得而然哉？天道已行矣。"],["吾闻至人，",{text:"尸居环堵之室",glossary:"gsc_weilei_shiju"},"，而百姓猖狂，不知所如往。"]]},{id:"gsc_weilei_s4",label:"不愿俎豆于贤人之间",sentences:[["今以畏垒之细民，而窃窃焉欲俎豆予于贤人之间，",{text:"我其杓之人邪",glossary:"gsc_weilei_biao"},"？"],["吾是以不释于老聃之言。」"]]},{id:"gsc_weilei_s5",label:"弟子劝受：寻常之沟与步仞之丘",sentences:[["弟子曰：「不然。夫寻常之沟，巨鱼无所还其体，而",{text:"鲵鳅",glossary:"gsc_weilei_niqiu"},"为之制；"],["步仞之丘陵，巨兽无所隐其躯，而孽狐为之祥。"],["且夫尊贤授能，先善与利，自古尧、舜以然，而况畏垒之民乎！夫子亦听矣！」"]]},{id:"gsc_weilei_s6",label:"离山失水：藏身不厌深眇",sentences:[["庚桑子曰：「小子来！夫",{text:"函车之兽",glossary:"gsc_weilei_hanche"},"，介而离山，则不免于网罟之患；"],["吞舟之鱼，荡而失水，则蚁能苦之。故鸟兽不厌高，鱼鳖不厌深。"],["夫全其形生之人，藏其身也，不厌深眇而已矣！"]]},{id:"gsc_weilei_s7",label:"简发而栉，数米而炊：繁细之治",sentences:[["且夫二子者，又何足以称扬哉！"],["是其于辩也，将妄凿垣墙而殖蓬蒿也，",{text:"简发而栉，数米而炊",glossary:"gsc_weilei_jianfa"},"，窃窃乎又何足以济世哉！"]]},{id:"gsc_weilei_s8",label:"举贤任知：竞争与大乱之本",sentences:[["举贤则民相轧，任知则民相盗。之数物者，不足以厚民。"],["民之于利甚勤，子有杀父，臣有杀君；正昼为盗，",{text:"日中穴阫",glossary:"gsc_weilei_xuepei"},"。"],["吾语女：大乱之本，必生于尧、舜之间，其末存乎",{text:"千世之后",glossary:"gsc_weilei_qianshi"},"。"],["千世之后，其必有人与人相食者也。」"]]}],p=[{id:"gsc_weilei_piande",term:"偏得老聃之道",pinyin:"piān dé lǎo dān zhī dào",meaning:"偏有不同训释，亦有联系遍、尽得者；不宜一面定为独得精髓，一面又定为只得局部。老聃之役常联系门人、弟子理解。人物身世按本篇叙述阅读。"},{id:"gsc_weilei_yongzhong",term:"拥肿之与居，鞅掌之为使",pinyin:"yōng zhǒng zhī yǔ jū, yāng zhǎng zhī wéi shǐ",meaning:"与不显智巧、朴拙者相居，任用不拘细节、劳作者等。拥肿、鞅掌的具体训释有差异，不直接将所有被描述者定为愚笨或毫无执著。"},{id:"gsc_weilei_huaran",term:"画然知者",pinyin:"huà rán zhì zhě",meaning:"显露智识的人。画然的具体含义有讨论空间；其臣之画然知者去之，涉及疏远、离去，不据此建立普遍排斥有知识者的原则。"},{id:"gsc_weilei_qieran",term:"挈然仁者",pinyin:"qiè rán rén zhě",meaning:"显露仁行的人。挈然的具体含义有讨论空间；其妾之挈然仁者远之，涉及疏远、离去，不据此建立普遍排斥有仁爱者的原则。"},{id:"gsc_weilei_rang",term:"畏垒大壤",pinyin:"wèi lěi dà rǎng",meaning:"畏垒大为丰收，壤常联系穰理解。原文未交代完整治理过程，不能直接改成庚桑楚什么都没有做。"},{id:"gsc_weilei_shizhu",term:"尸而祝之，社而稷之",pinyin:"shī ér zhù zhī, shè ér jì zhī",meaning:"以祭祀、神明般的方式尊奉他。尸涉及祭祀中代表受祭者的人；社、稷涉及土地与谷物之神。不是仅指普通感谢。"},{id:"gsc_weilei_shiju",term:"尸居环堵之室",pinyin:"shī jū huán dǔ zhī shì",meaning:"安静居处于简陋小室，尸居借静止作譬喻，不指实际尸体。猖狂在此可联系自由自得，不按现代违法狂妄义解释。"},{id:"gsc_weilei_biao",term:"我其杓之人邪",pinyin:"wǒ qí biāo zhī rén yé",meaning:"杓有标末、显为标表等解释，是疑难语句。不宜只按舀水勺推成小器量之人。结合俎豆于贤人之间，重点在是否成为被树立的贤者标志。"},{id:"gsc_weilei_niqiu",term:"鲵鳅",pinyin:"ní qiū",meaning:"小型水生动物，鲵有不同古义与分类解释，不宜直接释为大鱼。与巨鱼相对，用于小水域的譬喻。"},{id:"gsc_weilei_hanche",term:"函车之兽",pinyin:"hán chē zhī shòu",meaning:"足以容车、形体巨大的兽，具体解释有差异。函不必作吞食车解；介而离山、荡而失水共同强调离开适宜条件。"},{id:"gsc_weilei_jianfa",term:"简发而栉，数米而炊",pinyin:"jiǎn fà ér zhì, shǔ mǐ ér chuī",meaning:"逐根理发而梳，逐粒数米而炊，譬喻繁细而失其要。栉：梳理。不是一概否定细致工作。"},{id:"gsc_weilei_xuepei",term:"日中穴阫",pinyin:"rì zhōng xué péi",meaning:"白昼穿墙行盗。阫：墙；穴在此作穿凿动词。相轧指倾轧，相盗涉及欺盗与争夺。"},{id:"gsc_weilei_qianshi",term:"千世之后",pinyin:"qiān shì zhī hòu",meaning:"原文续言「其必有人与人相食者也」：用极端后果表达对竞争、逐利及文明秩序的激烈批评。是寓言人物的推论与警告，不是可验证的精确历史预报。"}],o=[{id:"gsc_teach_s1",label:"年已长：何处托业",sentences:[[{text:"南荣趎",glossary:"gsc_teach_nanrong"},"蹴然正坐曰：「若趎之年者已长矣，将",{text:"恶乎托业",glossary:"gsc_teach_tuoye"},"以及此言邪？」"],["庚桑子曰：「",{text:"全汝形，抱汝生，无使汝思虑营营",glossary:"gsc_teach_yingying"},"。若此三年，则可以及此言矣！」"]]},{id:"gsc_teach_s2",label:"目、耳、心与形：何以不能自得",sentences:[["南荣趎曰：「目之与形，吾不知其异也，而盲者不能自见；"],["耳之与形，吾不知其异也，而聋者不能自闻；"],["心之与形，吾不知其异也，而狂者不能自得。"],[{text:"形之与形亦辟矣",glossary:"gsc_teach_pi"},"，而物或间之邪？欲相求而不能相得。"]]},{id:"gsc_teach_s3",label:"听到耳中：尚未相契",sentences:[["今谓趎曰：『全汝形，抱汝生，无使汝思虑营营。』趎",{text:"勉闻道达耳",glossary:"gsc_teach_daer"},"矣！」"]]},{id:"gsc_teach_s4",label:"辞尽矣：蜂、鸡与化育之能",sentences:[["庚桑子曰：「辞尽矣，",{text:"奔蜂不能化藿蠋",glossary:"gsc_teach_huozhu"},"，",{text:"越鸡不能伏鹄卵",glossary:"gsc_teach_huluan"},"，鲁鸡固能矣！"],["鸡之与鸡，其德非不同也。有能与不能者，其才固有巨小也。"]]},{id:"gsc_teach_s5",label:"才小与转介：南见老子",sentences:[["今吾才小，",{text:"小足以化子",glossary:"gsc_teach_xiaozu"},"。子胡不南见老子！」"]]}],c=[{id:"gsc_teach_nanrong",term:"南荣趎",pinyin:"nán róng chú",meaning:"篇中向庚桑楚、老聃问道的人物。具体历史身份不详。蹴然正坐：肃然、惊动而端坐。"},{id:"gsc_teach_tuoye",term:"恶乎托业",pinyin:"wū hū tuō yè",meaning:"依托何种学习、实践或所业，才能达到所说？恶读 wū。不是只问职业安置。"},{id:"gsc_teach_yingying",term:"全汝形，抱汝生，无使汝思虑营营",pinyin:"quán rǔ xíng, bào rǔ shēng, wú shǐ rǔ sī lǜ yíng yíng",meaning:"保全形体、抱守生命，不使思虑纷扰奔忙。不能排除身体照料，也不等于停止所有思考。三年是本段的具体指引，不作普遍保证。"},{id:"gsc_teach_pi",term:"形之与形亦辟矣",pinyin:"xíng zhī yǔ xíng yì pì yǐ",meaning:"形与形相近、可相通等，辟的训释有讨论空间。物或间之的间指阻隔，可读 jiàn。不能将感官障碍简单归咎于执念。"},{id:"gsc_teach_daer",term:"勉闻道达耳",pinyin:"miǎn wén dào dá ěr",meaning:"勉力听闻，但只到耳中，尚未真正相契或落实。不是说他已经知道全部道理，也不是否定听闻的一切作用。"},{id:"gsc_teach_huozhu",term:"奔蜂不能化藿蠋",pinyin:"bēn fēng bù néng huà huò zhú",meaning:"借蜂与豆叶虫的化育关系作比，涉及古代对昆虫的认识。藿：豆叶；蠋：虫名。不是现代昆虫学中的确定结论。"},{id:"gsc_teach_huluan",term:"越鸡不能伏鹄卵",pinyin:"yuè jī bù néng fú hú luǎn",meaning:"借不同大小的鸡孵卵之能说明能力、条件的区别。伏：伏卵、孵育；鹄常指天鹅等大鸟。不能将比喻直接当作现代孵化事实。"},{id:"gsc_teach_xiaozu",term:"小足以化子",pinyin:"xiǎo zú yǐ huà zǐ",meaning:"来稿作小足以，语义与下文转介存在疑难；常见文本有不足以化子等写法，亦有联系小为不者。最终须依底本校定，不译成只够教化你。"}],h=[{id:"gsc_lao_s1",label:"赢粮而行：何与众人偕来",sentences:[["南荣趎",{text:"赢粮",glossary:"gsc_lao_yingliang"},"，七日七夜至老子之所。"],["老子曰：「子自楚之所来乎？」南荣趎曰：「唯。」"],["老子曰：「子何",{text:"与人偕来之众",glossary:"gsc_lao_xielai"},"也？」南荣趎惧然顾其后。"],["老子曰：「子不知吾所谓乎？」"],["南荣趎俯而惭，仰而叹，曰：「今者吾忘吾答，因失吾问。」"]]},{id:"gsc_lao_s2",label:"知、仁、义三患：我安逃此",sentences:[["老子曰：「何谓也？」"],["南荣趎曰：「不知乎人谓我",{text:"朱愚",glossary:"gsc_lao_zhuyu"},"，知乎反愁我躯；"],["不仁则害人，仁则反愁我身；不义则伤彼，义则反愁我己。"],["我安逃此而可？此三言者，趎之所患也。愿因楚而问之。」"]]},{id:"gsc_lao_s3",label:"眉睫之见：欲反情性而无由入",sentences:[["老子曰：「向吾见若眉睫之间，吾因以得汝矣。",{text:"今汝又言而信之",glossary:"gsc_lao_xinzhi"},"。"],["若",{text:"规规然",glossary:"gsc_lao_guigui"},"若丧父母，揭竿而求诸海也。"],["女亡人哉！惘惘乎，汝欲反汝情性而无由入，可怜哉！」"]]},{id:"gsc_lao_s4",label:"十日自愁：洒濯而犹有恶",sentences:[["南荣趎请入就舍，召其所好，去其所恶。",{text:"十日自愁",glossary:"gsc_lao_zichou"},"，复见老子。"],["老子曰：「汝自洒濯，孰哉郁郁乎！然而其中津津乎犹有恶也。"]]},{id:"gsc_lao_s5",label:"内外韄：束缚与相互闭塞",sentences:[["夫",{text:"外韄",glossary:"gsc_lao_wei"},"者不可繁而捉，将内揵；",{text:"内韄",glossary:"gsc_lao_neiwei"},"者不可缪而捉，将外揵；"],["外内韄者，道德不能持，而况",{text:"放道而行",glossary:"gsc_lao_fangdao"},"者乎！」"]]},{id:"gsc_lao_s6",label:"闻道如饮药加病：愿闻卫生之经",sentences:[["南荣趎曰：「里人有病，里人问之，病者能言其病，然",{text:"其病病者犹未病",glossary:"gsc_lao_bingbing"},"也。"],["若趎之闻大道，譬犹饮药以加病也。趎愿闻",{text:"卫生之经",glossary:"gsc_lao_weisheng"},"而已矣。」"]]},{id:"gsc_lao_s7",label:"卫生九问：抱一、止已与求己",sentences:[["老子曰：「卫生之经，",{text:"能抱一乎",glossary:"gsc_lao_baoyi"},"！能勿失乎！能无卜筮而知吉凶乎！"],["能止乎！能已乎！能舍诸人而求诸己乎！"],["能",{text:"翛然",glossary:"gsc_lao_xiaotong"},"乎！能",{text:"侗然",glossary:"gsc_lao_tongran"},"乎！能儿子乎！"]]},{id:"gsc_lao_s8",label:"儿子三德：和、握与视",sentences:[["儿子终日",{text:"嗥而嗌不嗄",glossary:"gsc_lao_haosha"},"，和之至也；"],["终日握而",{text:"手不掜",glossary:"gsc_lao_nie"},"，共其德也；"],["终日视而目不瞬，偏不在外也。"],["行不知所之，居不知所为，",{text:"与物委蛇而同其波",glossary:"gsc_lao_weiyi"},"。是卫生之经已。」"]]},{id:"gsc_lao_s9",label:"非至人之德：冰解冻释",sentences:[["南荣趎曰：「然则是至人之德已乎？」"],["曰：「非也。是乃所谓",{text:"冰解冻释",glossary:"gsc_lao_bingjie"},"者。"],["夫至人者，相与交食乎地而交乐乎天，不以人物利害",{text:"相撄",glossary:"gsc_lao_ying"},"，"],["不相与为怪，不相与为谋，不相与为事，翛然而往，侗然而来。"],["是谓卫生之经已。」"]]},{id:"gsc_lao_s10",label:"再问是否至极：回到儿子之喻",sentences:[["曰：「然则是至乎？」"],["曰：「未也。吾固告汝曰：『能儿子乎！』"],["儿子动不知所为，行不知所之，身若槁木之枝而心若死灰。"],["若是者，祸亦不至，福亦不来。",{text:"祸福无有，恶有人灾",glossary:"gsc_lao_renzai"},"也！」"]]}],_=[{id:"gsc_lao_yingliang",term:"赢粮",pinyin:"yíng liáng",meaning:"携带粮食。楚之所在这里指庚桑楚处，不是未经辨析便指楚国。"},{id:"gsc_lao_xielai",term:"与人偕来之众",pinyin:"yǔ rén xié lái zhī zhòng",meaning:"以许多人同行作反问，结合后文可联系所携带的意见、分别与忧患。不必逐一给虚拟同行者指定固定身份。"},{id:"gsc_lao_zhuyu",term:"朱愚",pinyin:"zhū yú",meaning:"甚愚、大愚等，朱的训释有讨论空间。三患涉及他人的评价、自身负担与对他人的伤害。"},{id:"gsc_lao_xinzhi",term:"今汝又言而信之",pinyin:"jīn rǔ yòu yán ér xìn zhī",meaning:"你现在的言说又证实了先前所见。信可联系验证理解，不宜只译成你相信自己所说。"},{id:"gsc_lao_guigui",term:"规规然",pinyin:"guī guī rán",meaning:"拘谨、不自得的样子。揭竿求诸海用不相称的工具、范围作譬喻，不建立具体海中寻物技术。"},{id:"gsc_lao_zichou",term:"十日自愁",pinyin:"shí rì zì chóu",meaning:"自苦、自省或整治自身等，有不同训释。召好去恶的好恶所指亦有空间，不将它直接定为十天心理治疗。"},{id:"gsc_lao_wei",term:"外韄",pinyin:"wài huò",meaning:"外在的束缚。韄：束缚；揵涉及闭塞、固结，读音与句法有讨论空间。不可直接将「将内揵」定为从内关闭的操作指令。"},{id:"gsc_lao_neiwei",term:"内韄",pinyin:"nèi huò",meaning:"内在的束缚。与外韄并列，说明内外皆可能受缚；不可直接将「将外揵」定为从外关闭的操作指令。"},{id:"gsc_lao_fangdao",term:"放道而行",pinyin:"fǎng dào ér xíng",meaning:"放有依、仿行等解释，也有不同训法，不宜只定为放弃道。与道德不能持相接，需据底本注释统一。"},{id:"gsc_lao_bingbing",term:"其病病者犹未病",pinyin:"qí bìng bìng zhě yóu wèi bìng",meaning:"病字叠用，涉及使人病者、以病为病等不同解释。整体表达能言其病仍未解决困扰，不强定为已经诊明病根。"},{id:"gsc_lao_weisheng",term:"卫生之经",pinyin:"wèi shēng zhī jīng",meaning:"护卫、保全生命的常道。不是现代公共卫生，也不是具体医学疗程。"},{id:"gsc_lao_baoyi",term:"能抱一乎",pinyin:"néng bào yī hū",meaning:"能保有统一、完整的生命安顿吗？一可联系道与不分裂理解，不将其直接定为某个可指认的内在实体。"},{id:"gsc_lao_xiaotong",term:"翛然",pinyin:"xiāo rán",meaning:"无拘无束的样子。原文与侗然并列；不等于失去全部知识或欲望。"},{id:"gsc_lao_tongran",term:"侗然",pinyin:"tóng rán",meaning:"朴直未显智巧的样子。侗的读音有差异，宜依注本统一；与翛然同属对自在状态的描写。"},{id:"gsc_lao_haosha",term:"嗥而嗌不嗄",pinyin:"háo ér yì bù shà",meaning:"哭号而喉咙不哑，是婴儿之和的理想化描写，不作现代生理事实。嗌：喉咙；嗄：声音嘶哑。"},{id:"gsc_lao_nie",term:"手不掜",pinyin:"shǒu bù nǐ",meaning:"掜涉及捏、用力握等，字形、音读与训释有讨论空间。结合终日握，强调不强作的持握，不直接等同完全不用肌力。"},{id:"gsc_lao_weiyi",term:"与物委蛇而同其波",pinyin:"yǔ wù wēi yí ér tóng qí bō",meaning:"随顺事物变化而同其波流。委蛇读 wēi yí，不是蛇这一动物；不等于对一切要求无条件服从。"},{id:"gsc_lao_bingjie",term:"冰解冻释",pinyin:"bīng jiě dòng shì",meaning:"像冰冻开始解除般，束缚获得松动。不是医学上病情痊愈，也不能据此机械划出全篇修养等级。"},{id:"gsc_lao_ying",term:"相撄",pinyin:"xiāng yīng",meaning:"相互扰动、纠缠。交食乎地、交乐乎天可联系共同生活与自然安顿，不按肉身到天上吃乐解。"},{id:"gsc_lao_renzai",term:"祸福无有，恶有人灾",pinyin:"huò fú wú yǒu, wū yǒu rén zāi",meaning:"以强烈理想表达不被祸福、利害之执拘系。恶读 wū，意为哪里、怎么；不是现实免伤免灾规律。"}],y=[{id:"gsc_inner_s1",label:"宇泰定：天光、恒与天民",sentences:[[{text:"宇泰定者",glossary:"gsc_inner_yutai"},"，发乎天光。"],["发乎天光者，",{text:"人见其人，物见其物",glossary:"gsc_inner_renjian"},"。人有修者，乃今有恒。"],["有恒者，人舍之，天助之。人之所舍，谓之",{text:"天民",glossary:"gsc_inner_tianmin"},"；天之所助，谓之",{text:"天子",glossary:"gsc_inner_tianzi"},"。"]]},{id:"gsc_inner_s2",label:"学、行、辩的限度：知止",sentences:[["学者，学其所不能学也？行者，行其所不能行也？辩者，辩其所不能辩也？"],["知止乎其所不能知，至矣！若有不即是者，",{text:"天钧",glossary:"gsc_inner_tianjun"},"败之。"]]},{id:"gsc_inner_s3",label:"备物养形，敬中达彼",sentences:[[{text:"备物将以形",glossary:"gsc_inner_beiwu"},"，",{text:"藏不虞以生心",glossary:"gsc_inner_buyu"},"，敬中以达彼。"],["若是而万恶至者，皆天也，而非人也，不足以",{text:"滑成",glossary:"gsc_inner_gucheng"},"，不可内于灵台。"]]},{id:"gsc_inner_s4",label:"灵台有持：持守而不固执",sentences:[[{text:"灵台",glossary:"gsc_inner_lingtai"},"者有持，而不知其所持而不可持者也。"],[{text:"不见其诚己而发",glossary:"gsc_inner_chengji"},"，每发而不当；业入而不舍，每更为失。"]]},{id:"gsc_inner_s5",label:"显明与幽间：不善与独行",sentences:[["为不善乎显明之中者，人得而诛之；为不善乎幽间之中者，",{text:"鬼得而诛之",glossary:"gsc_inner_gui"},"。"],["明乎人、明乎鬼者，然后能独行。"]]},{id:"gsc_inner_s6",label:"券内与券外：无名和期费",sentences:[[{text:"券内者",glossary:"gsc_inner_quan"},"，行乎无名；券外者，志乎期费。"],["行乎无名者，唯庸有光；志乎期费者，唯",{text:"贾人",glossary:"gsc_inner_gu"},"也。"],[{text:"人见其跂，犹之魁然",glossary:"gsc_inner_qi"},"。"]]},{id:"gsc_inner_s7",label:"与物相处：容身、容人与无亲",sentences:[[{text:"与物穷者",glossary:"gsc_inner_qiongqie"},"，物入焉；",{text:"与物且者",glossary:"gsc_inner_wuqie"},"，其身之不能容，焉能容人！"],["不能容人者无亲，无亲者尽人。"]]},{id:"gsc_inner_s8",label:"志与阴阳：心如何参与耗损",sentences:[["兵莫惨于志，",{text:"镆铘",glossary:"gsc_inner_moye"},"为下；"],["寇莫大于阴阳，无所逃于天地之间。",{text:"非阴阳贼之，心则使之也",glossary:"gsc_inner_yinyang"},"。"]]}],u=[{id:"gsc_inner_yutai",term:"宇泰定者",pinyin:"yǔ tài dìng zhě",meaning:"宇可联系心之居处、心胸理解，泰定指安定。天光联系自然的明照、通达，不必按身体发出可见光解释。"},{id:"gsc_inner_renjian",term:"人见其人，物见其物",pinyin:"rén jiàn qí rén, wù jiàn qí wù",meaning:"人、物各得显现，或各见其所见等，有不同解释。不能只定为他人见到修道者的真实身份，也不必拟人物具有人的视觉判断。"},{id:"gsc_inner_tianmin",term:"天民",pinyin:"tiān mín",meaning:"人之所舍者谓之天民。本段从人舍、天助说明两种称谓，具有天与人的对举意味，不直接按帝王称号解释。"},{id:"gsc_inner_tianzi",term:"天子",pinyin:"tiān zǐ",meaning:"天之所助者谓之天子。此处与天民对举，不直接按帝王称号解释，也不能保证受世俗认可者必获自然庇护。"},{id:"gsc_inner_tianjun",term:"天钧",pinyin:"tiān jūn",meaning:"自然的均平、运转或调均等。败之写强作与自然条件相违的后果，不是已经验证的宇宙奖惩机制。"},{id:"gsc_inner_beiwu",term:"备物将以形",pinyin:"bèi wù jiāng yǐ xíng",meaning:"准备、具备所需之物以养护形体等。将的训释与字形有讨论空间，不能由后文心的持守否定身体照料。"},{id:"gsc_inner_buyu",term:"藏不虞以生心",pinyin:"cáng bù yú yǐ shēng xīn",meaning:"不虞涉及不测、未料之事，藏与生心的句法有不同解释。可联系面对不测而保养心神，不直接译成压抑所有忧虑。"},{id:"gsc_inner_gucheng",term:"滑成",pinyin:"gǔ chéng",meaning:"扰乱已有的安顿、所成等。滑在扰乱义常读 gǔ；内于灵台的内联系纳入理解，可依注本读 nà。"},{id:"gsc_inner_lingtai",term:"灵台",pinyin:"líng tái",meaning:"心、心神之居处的譬喻。有持而不知所持、不可持的关系有解释空间，不立即设定心所持的是一个不可言说实体。"},{id:"gsc_inner_chengji",term:"不见其诚己而发",pinyin:"bù jiàn qí chéng jǐ ér fā",meaning:"未明察自身实情、未落实于己便发动等。诚己的具体解释有差异，不只等于主观上觉得自己真诚。业入也不强定为现代心理学的执念。"},{id:"gsc_inner_gui",term:"鬼得而诛之",pinyin:"guǐ dé ér zhū zhī",meaning:"借幽隐之处亦有惩诛说明不善不可因无人看见而免除。保留古代鬼神语境，不作为现代可验证的超自然事实。"},{id:"gsc_inner_quan",term:"券内者、券外者",pinyin:"quàn nèi zhě、quàn wài zhě",meaning:"券借契券、契合关系作譬喻，内外指向自身安顿与向外求取等。不是现实中与道签订的契约。期费常联系预期报偿、求取名利理解。"},{id:"gsc_inner_gu",term:"贾人",pinyin:"gǔ rén",meaning:"商人，借交易求偿比喻处世方式。此处批评将行动变成求取报偿的方式，不直接证明所有商业活动都不善。"},{id:"gsc_inner_qi",term:"人见其跂，犹之魁然",pinyin:"rén jiàn qí qì, yóu zhī kuí rán",meaning:"跂可联系企求、踮足而望，魁然涉及高大、显著等。整句有训释空间，不把比喻改成确定的人格诊断。"},{id:"gsc_inner_qiongqie",term:"与物穷者",pinyin:"yǔ wù qióng zhě",meaning:"穷的具体训释有差异，不能仅按现代穷困解释。整体涉及与物相处如何影响容身容人，应保留疑难。"},{id:"gsc_inner_wuqie",term:"与物且者",pinyin:"yǔ wù qiě zhě",meaning:"且的具体训释有差异，不能仅按暂且将就解释。与与物穷者并举，说明与物相处方式影响能否容人。"},{id:"gsc_inner_moye",term:"镆铘",pinyin:"mò yé",meaning:"古代名剑，亦写作莫邪等。兵莫惨于志以强烈比喻写志意造成的冲突与耗损，不等于所有意志、目标都有害。"},{id:"gsc_inner_yinyang",term:"非阴阳贼之，心则使之也",pinyin:"fēi yīn yáng zéi zhī, xīn zé shǐ zhī yě",meaning:"转而追问心如何参与自然变化带来的耗损。不应推成寒暑、疾病、灾害全无外在危险，或受害全由受害者的心造成。"}],m=[{id:"gsc_gate_s1",label:"分、成与毁：备的限度",sentences:[[{text:"道通其分",glossary:"gsc_gate_fen"},"也，其成也毁也。所恶乎分者，",{text:"其分也以备",glossary:"gsc_gate_bei"},"。"],["所以恶乎备者？其有以备。"]]},{id:"gsc_gate_s2",label:"出而不反：鬼、得死与有形无形",sentences:[["故",{text:"出而不反，见其鬼",glossary:"gsc_gate_gui"},"。出而得，是谓得死。灭而有实，鬼之一也。"],[{text:"以有形者象无形者而定",glossary:"gsc_gate_xiang"},"矣！"]]},{id:"gsc_gate_s3",label:"有实无处，有长无本剽",sentences:[["出无本，入无窍，有实而无乎处，有长而无乎",{text:"本剽",glossary:"gsc_gate_benbiao"},"，有所出而无窍者有实。"],["有实而无乎处者，",{text:"宇",glossary:"gsc_gate_yuzhou"},"也；有长而无本剽者，",{text:"宙",glossary:"gsc_gate_zhou"},"也。"]]},{id:"gsc_gate_s4",label:"生死出入：天门无有",sentences:[["有乎生，有乎死；有乎出，有乎入。"],["入出而无见其形，是谓",{text:"天门",glossary:"gsc_gate_tianmen"},"。天门者，无有也。"]]},{id:"gsc_gate_s5",label:"万物出乎无有：圣人藏乎是",sentences:[[{text:"万物出乎无有",glossary:"gsc_gate_wuyou"},"。有不能以有为有，必出乎无有，而",{text:"无有一无有",glossary:"gsc_gate_yiwuyou"},"。"],[{text:"圣人藏乎是",glossary:"gsc_gate_cang"},"。"]]}],b=[{id:"gsc_gate_fen",term:"道通其分",pinyin:"dào tōng qí fēn",meaning:"道贯通事物的区分。成也毁也可联系一形态成立同时改变、解除另一形态，不等于所有建成与毁坏在实践中毫无区别。"},{id:"gsc_gate_bei",term:"其分也以备",pinyin:"qí fēn yě yǐ bèi",meaning:"备有具备、完备等解释，句法有讨论空间；原文续说「其有以备」。可联系以有限分别求取完备所遇的困难，不直接宣布所有准备与分类都有害。"},{id:"gsc_gate_gui",term:"出而不反，见其鬼",pinyin:"chū ér bù fǎn, jiàn qí guǐ",meaning:"涉及向外而不返、鬼与死的关系，属于疑难语群。鬼可能关联死后形态、精神或幽隐者，不径直译成逐名利者变成鬼。"},{id:"gsc_gate_xiang",term:"以有形者象无形者而定",pinyin:"yǐ yǒu xíng zhě xiàng wú xíng zhě ér dìng",meaning:"用有形者比拟、指示无形者，或据此定说等。定的语气和褒贬有解释空间，不能只译成这样便能安顿于道。"},{id:"gsc_gate_benbiao",term:"本剽",pinyin:"běn biāo",meaning:"本与末、起端与终端等。剽常联系末、标理解，不按现代剽窃义解释。长指延展，不只指物体长度。"},{id:"gsc_gate_yuzhou",term:"宇",pinyin:"yǔ",meaning:"有实而无乎处者，宇也：关联无固定处所的广延，可与空间对读。不直接等同现代物理学对宇宙的定义。"},{id:"gsc_gate_zhou",term:"宙",pinyin:"zhòu",meaning:"有长而无本剽者，宙也：关联无可指定始末的延续，可与时间对读。与宇并列而分指两面。"},{id:"gsc_gate_tianmen",term:"天门",pinyin:"tiān mén",meaning:"出入生成而不能指认为一个固定形体的门之譬喻，不是宇宙中可找到的一处实体门户。"},{id:"gsc_gate_wuyou",term:"万物出乎无有",pinyin:"wàn wù chū hū wú yǒu",meaning:"以无有说明生成根本不能归结为一件已经存在的物。无有不必等同绝对虚无，也不预先设成一种可命名的特殊物质。"},{id:"gsc_gate_yiwuyou",term:"无有一无有",pinyin:"wú yǒu yī wú yǒu",meaning:"一的句法有讨论空间，可联系无有亦不能再被划分、对象化理解。不直接凭此确定完整的单一本体学说。"},{id:"gsc_gate_cang",term:"圣人藏乎是",pinyin:"shèng rén cáng hū shì",meaning:"圣人在此安顿、藏身。与篇首不愿显为贤者相接，不只指地理上的隐居，也不意味着脱离万物与日常生活。"}],x=[{id:"gsc_ancient_s1",label:"知有所至：未始有物",sentences:[["古之人，其知有所至矣。恶乎至？"],["有以为",{text:"未始有物",glossary:"gsc_ancient_weishi"},"者，至矣，尽矣，弗可以加矣！"]]},{id:"gsc_ancient_s2",label:"其次：生为丧，死为反",sentences:[["其次以为有物矣，将",{text:"以生为丧",glossary:"gsc_ancient_sangfan"},"也，以死为反也，是以分已。"]]},{id:"gsc_ancient_s3",label:"又次：无有、生、死为一体",sentences:[["其次曰始无有，既而有生，生俄而死。"],["以无有为首，以生为体，以死为",{text:"尻",glossary:"gsc_ancient_kao"},"。"],["孰知",{text:"有无死生之一守",glossary:"gsc_ancient_yishou"},"者，吾与之为友。"]]},{id:"gsc_ancient_s4",label:"三者虽异：公族与非一",sentences:[["是",{text:"三者虽异，公族也",glossary:"gsc_ancient_gongzu"},"。"],[{text:"昭景",glossary:"gsc_ancient_zhaojing"},"也，",{text:"著戴",glossary:"gsc_ancient_zhudai"},"也；",{text:"甲氏",glossary:"gsc_ancient_jiashi"},"也，",{text:"著封",glossary:"gsc_ancient_zhufeng"},"也：",{text:"非一也",glossary:"gsc_ancient_feiyi"},"。"]]}],q=[{id:"gsc_ancient_weishi",term:"未始有物",pinyin:"wèi shǐ yǒu wù",meaning:"未曾开始以物的分别确立所知等，亦有其他解释。原文给予最高评价，但不能直接当作现实物体完全不存在的事实断言。"},{id:"gsc_ancient_sangfan",term:"以生为丧",pinyin:"yǐ shēng wéi sàng",meaning:"将生视为丧失（原文续作「以死为反也」），是本段列出的第二种认识。原文又说已有分别，不能脱离比较将其定为全篇主张人应求死。"},{id:"gsc_ancient_kao",term:"尻",pinyin:"kāo",meaning:"臀部、后部。与首、体组成身体譬喻，说明无有、生、死可以连读，不只作为线性时间的尾端。"},{id:"gsc_ancient_yishou",term:"有无死生之一守",pinyin:"yǒu wú sǐ shēng zhī yī shǒu",meaning:"有无死生相通、同属一体的守持，具体句法有解释空间。不能据相通取消实际死亡或生活差异。"},{id:"gsc_ancient_gongzu",term:"三者虽异，公族也",pinyin:"sān zhě suī yì, gōng zú yě",meaning:"三种认识虽有差异，仍如同一公族。说明相近与分别并存，不等于三者完全相同或无高下。"},{id:"gsc_ancient_zhaojing",term:"昭景",pinyin:"zhāo jǐng",meaning:"涉及族氏的古义，训释与字形有争议。与著戴、甲氏、著封并列，可把握同族而非一的譬喻，不将其确定为楚国王族姓氏。"},{id:"gsc_ancient_zhudai",term:"著戴",pinyin:"zhù dài",meaning:"戴的古义有争议，或联系支派、职事。与昭景等并举，说明同族而非一，不据此复原宗族谱系。"},{id:"gsc_ancient_jiashi",term:"甲氏",pinyin:"jiǎ shì",meaning:"族氏名，具体所指有争议。与昭景、著戴、著封并列，共同说明同族而非一。"},{id:"gsc_ancient_zhufeng",term:"著封",pinyin:"zhù fēng",meaning:"封的古义有争议，或联系封邑、封别。四者并举以说同族而非一，不将所有词都确定为楚国王族姓氏。"},{id:"gsc_ancient_feiyi",term:"非一也",pinyin:"fēi yī yě",meaning:"并非完全同一。应保留原文对差异的强调，不只译成名字不同但全无实质区别。"}],f=[{id:"gsc_yishi_s1",label:"有生黬与移是：先提出疑难",sentences:[[{text:"有生黬也",glossary:"gsc_yishi_shengyan"},"，披然曰「",{text:"移是",glossary:"gsc_yishi_yishi"},"」。"],["尝言「移是」，非所言也。虽然，不可知者也。"]]},{id:"gsc_yishi_s2",label:"腊体与观室：部分、整体和转移",sentences:[["腊者之有",{text:"膍胲",glossary:"gsc_yishi_pigai"},"，可散而不可散也；"],[{text:"观室者周于寝庙，又适其偃",glossary:"gsc_yishi_yan"},"焉！为是举「移是」。"]]},{id:"gsc_yishi_s3",label:"以生为本，以知为师：乘是非",sentences:[["请尝言「移是」：是以生为本，以知为师，因以乘是非。"],["果有名实，因",{text:"以己为质",glossary:"gsc_yishi_zhi"},"，使人以为己节，因",{text:"以死偿节",glossary:"gsc_yishi_changjie"},"。"]]},{id:"gsc_yishi_s4",label:"用、不用、彻与穷：今人的尺度",sentences:[["若然者，以用为知，以不用为愚；",{text:"以彻为名，以穷为辱",glossary:"gsc_yishi_che"},"。"],["「移是」，今之人也，是",{text:"蜩与学鸠同于同",glossary:"gsc_yishi_tiaojiu"},"也。"]]}],k=[{id:"gsc_yishi_shengyan",term:"有生黬也",pinyin:"yǒu shēng yǎn yě",meaning:"疑难句，黬有黑斑、黑点等训释，也有涉及字形、句读的不同处理。不直接把它定为生命中的执著黑斑。"},{id:"gsc_yishi_yishi",term:"移是",pinyin:"yí shì",meaning:"疑难用语，有转移所是、迁移是非、推移所执等解释。不能只把移等同执著；可结合后文对生、知、名实、用愚的判断阅读。"},{id:"gsc_yishi_pigai",term:"腊者之有膍胲",pinyin:"xī zhě zhī yǒu pí gǎi",meaning:"腊有干肉、干制兽体等解释，此义可读 xī，不必作腊祭。膍胲涉及胃肠、足部或体内组织等，具体训释有差异。整体与部分的譬喻可保留，细节宜依底本校定。"},{id:"gsc_yishi_yan",term:"观室者周于寝庙，又适其偃",pinyin:"guān shì zhě zhōu yú qǐn miào, yòu shì qí yǎn",meaning:"观看居室而遍及不同处所，偃有厕、侧处等解释。不能直接认定这是批评参观者始终未走出房子的完整寓言。"},{id:"gsc_yishi_zhi",term:"以己为质",pinyin:"yǐ jǐ wéi zhì",meaning:"以自己作为质押、保证。质押的是自身，不只指名誉；与以死偿节相接，突出名实承诺可能反过来拘束生命。"},{id:"gsc_yishi_changjie",term:"以死偿节",pinyin:"yǐ sǐ cháng jié",meaning:"以死亡偿付、维护所立之节。是对生命被名节要求反向支配的强烈批评，不等于所有承诺都无价值，也不作为自伤的建议。"},{id:"gsc_yishi_che",term:"以彻为名，以穷为辱",pinyin:"yǐ chè wéi míng, yǐ qióng wéi rǔ",meaning:"以通达、显达为名誉，以受困、不通为耻辱。彻不只指内在的哲学通达，可联系外在成就尺度理解。"},{id:"gsc_yishi_tiaojiu",term:"蜩与学鸠同于同",pinyin:"tiáo yǔ xué jiū tóng yú tóng",meaning:"借《逍遥游》中蜩与学鸠的形象说明相近的局限。学鸠的物种、学字训释有讨论空间，不强定为斑鸠；同于同也不宜补成二者以为彼此不同。"}],z=[{id:"gsc_foursix_s1",label:"蹍足之喻：陌生人、兄与大亲",sentences:[[{text:"蹍",glossary:"gsc_foursix_nian"},"市人之足，则辞以",{text:"放骜",glossary:"gsc_foursix_fangao"},"，",{text:"兄则以妪，大亲则已",glossary:"gsc_foursix_yu"},"矣。"]]},{id:"gsc_foursix_s2",label:"五个至：礼、义、知、仁、信",sentences:[["故曰：",{text:"至礼有不人",glossary:"gsc_foursix_buren"},"，至义不物，至知不谋，至仁无亲，",{text:"至信辟金",glossary:"gsc_foursix_bijin"},"。"]]},{id:"gsc_foursix_s3",label:"彻、解、去、达：四种解除",sentences:[["彻",{text:"志之勃",glossary:"gsc_foursix_bomiu"},"，解",{text:"心之谬",glossary:"gsc_foursix_miu"},"，去德之累，达道之塞。"]]},{id:"gsc_foursix_s4",label:"四组六项：志、心、德、道",sentences:[["贵富显严名利六者，勃志也；"],["容动色理气意六者，谬心也；"],[{text:"恶欲喜怒哀乐",glossary:"gsc_foursix_qingxu"},"六者，累德也；"],[{text:"去就取与知能",glossary:"gsc_foursix_quyu"},"六者，塞道也。"]]},{id:"gsc_foursix_s5",label:"不荡胸中：正、静、明、虚",sentences:[["此",{text:"四六",glossary:"gsc_foursix_siliu"},"者不荡胸中则正，正则静，静则明，明则虚，虚则",{text:"无为而无不为",glossary:"gsc_foursix_wuwei"},"也。"]]}],w=[{id:"gsc_foursix_nian",term:"蹍",pinyin:"niǎn",meaning:"踩、践踏。市人可联系陌生人、众人理解，开头以不同亲疏关系中的致歉方式作譬喻。"},{id:"gsc_foursix_fangao",term:"辞以放骜",pinyin:"cí yǐ fàng ào",meaning:"放骜是疑难词，传统有恭敬、逊谢等解释，不宜按现代放纵傲慢义直接译成傲慢道歉。音读与字形最终依注本统一。"},{id:"gsc_foursix_yu",term:"兄则以妪，大亲则已",pinyin:"xiōng zé yǐ yù, dà qīn zé yǐ",meaning:"对兄长以亲和言语相慰，对至亲无需同样的礼仪性辞谢。妪的读音、训释有差异；不是说亲人受伤就不必关心或处理。"},{id:"gsc_foursix_buren",term:"至礼有不人",pinyin:"zhì lǐ yǒu bù rén",meaning:"最高之礼未必呈现通常的人为礼仪、待人形式等，有不同解释。不直接定为完全取消人我区别，也不应以此否定尊重与同意。"},{id:"gsc_foursix_bijin",term:"至信辟金",pinyin:"zhì xìn pì jīn",meaning:"最高之信不必依金、契券等外在凭证，有不同解释。辟联系避理解。不应据此建议现实交易不留记录、不立必要契约。"},{id:"gsc_foursix_bomiu",term:"志之勃",pinyin:"zhì zhī bó",meaning:"彻志之勃：志意中的悖乱、激荡。勃可联系悖乱、激荡，不能只按一时冲动理解。"},{id:"gsc_foursix_miu",term:"心之谬",pinyin:"xīn zhī miù",meaning:"解心之谬：心中的缠结错乱。谬可联系缪、缠绕与错乱，不能只按认知错误理解。"},{id:"gsc_foursix_siliu",term:"四六",pinyin:"sì liù",meaning:"四组六项，共二十四项。原文联系志、心、德、道的扰动，不明确把四者排列成由外至内的实体层级。"},{id:"gsc_foursix_qingxu",term:"恶欲喜怒哀乐",pinyin:"wù yù xǐ nù āi lè",meaning:"厌恶、欲求与喜怒哀乐。原文对其累德有尖锐评价；又以不荡胸中为条件，不等于现实情绪一出现就证明有罪或修养失败。"},{id:"gsc_foursix_quyu",term:"去就取与知能",pinyin:"qù jiù qǔ yǔ zhī néng",meaning:"离去、趋就、取、给予、认识、能力等。并非宣布所有离去、帮助、学习和技能都有害，而是反省这些活动如何拘塞处身。"},{id:"gsc_foursix_wuwei",term:"无为而无不为",pinyin:"wú wéi ér wú bù wéi",meaning:"不强作而能妥善应接的理想表达。不是无所不能、任一任务必定成功，也不是停止所有行动。"}],P=[{id:"gsc_necessary_s1",label:"道、德、生、性：为与失",sentences:[[{text:"道者，德之钦",glossary:"gsc_necessary_qin"},"也；生者，德之光也；性者，生之质也。"],[{text:"性之动谓之为，为之伪谓之失",glossary:"gsc_necessary_wei"},"。"]]},{id:"gsc_necessary_s2",label:"知与动：不得已之德",sentences:[[{text:"知者，接也；知者，谟也",glossary:"gsc_necessary_mo"},"。知者之所不知，犹睨也。"],["动以不得已之谓德，",{text:"动无非我之谓治",glossary:"gsc_necessary_feiwo"},"，名相反而实相顺也。"]]},{id:"gsc_necessary_s3",label:"羿、圣人与全人：天和人",sentences:[["羿工乎中微而拙乎使人无己誉；圣人工乎天而拙乎人；"],["夫",{text:"工乎天而俍乎人",glossary:"gsc_necessary_liang"},"者，唯全人能之。"],["虽虫能虫，虽虫能天。",{text:"全人恶天，恶人之天",glossary:"gsc_necessary_wutian"},"，而况吾天乎人乎！"]]},{id:"gsc_necessary_s4",label:"以天下为笼：所好与笼取",sentences:[["一雀适羿，羿必得之，或也。以天下为之笼，则雀无所逃。"],["是故汤以",{text:"胞人",glossary:"gsc_necessary_paoren"},"笼伊尹，秦穆公以五羊之皮笼百里奚。"],["是故非以其所好笼之而可得者，无有也。"]]},{id:"gsc_necessary_s5",label:"刑者与忘人：毁誉、死生",sentences:[[{text:"介者拸画",glossary:"gsc_necessary_jiezhe"},"，外非誉也。",{text:"胥靡",glossary:"gsc_necessary_xumi"},"登高而不惧，遗死生也。"],["夫",{text:"复谐不馈",glossary:"gsc_necessary_fuxie"},"而忘人，忘人，因以为天人矣！"]]},{id:"gsc_necessary_s6",label:"同乎天和：敬侮与喜怒",sentences:[["故敬之而不喜，侮之而不怒者，唯",{text:"同乎天和",glossary:"gsc_necessary_tianhe"},"者为然。"],[{text:"出怒不怒",glossary:"gsc_necessary_chunu"},"，则怒出于不怒矣；",{text:"出为无为",glossary:"gsc_necessary_chuwei"},"，则为出于无为矣！"]]},{id:"gsc_necessary_s7",label:"平气、顺心与不得已：篇末收束",sentences:[["欲静则平气，欲神则顺心。"],["有为也欲当，则",{text:"缘于不得已",glossary:"gsc_necessary_budeyi"},"。不得已之类，圣人之道。"]]}],T=[{id:"gsc_necessary_qin",term:"道者，德之钦",pinyin:"dào zhě, dé zhī qīn",meaning:"钦有尊、所尊奉等解释，亦有联系根本者。原文写道与德的关系，不直接等同道先产生德的时间生成公式。"},{id:"gsc_necessary_wei",term:"性之动谓之为，为之伪谓之失",pinyin:"xìng zhī dòng wèi zhī wéi, wéi zhī wěi wèi zhī shī",meaning:"性的活动称为为，为转为造作、伪饰等则称失。伪的古义不只涉及蓄意欺骗；自然活动与人为加工的边界仍须依情境辨析。"},{id:"gsc_necessary_mo",term:"知者，接也；知者，谟也",pinyin:"zhī zhě, jiē yě; zhī zhě, mó yě",meaning:"知涉及接触、应接与思量谋议。不能直接定为两种严格分离的被动感官与主动计划，也不必认定两者全无价值。"},{id:"gsc_necessary_feiwo",term:"动无非我之谓治",pinyin:"dòng wú fēi wǒ zhī wèi zhì",meaning:"行动不违自身、无外在异己强作等，有不同解释。不能直接作为凡我想做便是合理的原则；名相反而实相顺提示与不得已之动连读。"},{id:"gsc_necessary_liang",term:"工乎天而俍乎人",pinyin:"gōng hū tiān ér liáng hū rén",meaning:"俍有善、工巧等训释，字形与音读有讨论空间。天、人也不只等于天道知识与社交技能，不机械建立羿、圣人、全人的固定等级。"},{id:"gsc_necessary_wutian",term:"全人恶天，恶人之天",pinyin:"quán rén wū tiān, wū rén zhī tiān",meaning:"恶有何、哪里等疑问用法，可联系全人何必区分天、人之天理解。句读与训释有争议，不直接译成全人厌恶天道或厌恶彰显天道。"},{id:"gsc_necessary_paoren",term:"胞人",pinyin:"páo rén",meaning:"联系庖人、厨役理解。伊尹、百里奚的故事用于所好与笼取的譬喻，不未经校验补写伊尹喜欢烹饪、百里奚以自由为所好等心理。"},{id:"gsc_necessary_jiezhe",term:"介者拸画",pinyin:"jiè zhě chǐ huà",meaning:"介者常联系受刑者理解，拸画有去文饰、弃分别等解释。字形音义有争议，不强定为断足者不在乎画地为牢。"},{id:"gsc_necessary_xumi",term:"胥靡",pinyin:"xū mí",meaning:"被拘系、服劳役者等。登高不惧是古代譬喻，不能作为受刑者没有恐惧、可以不受保护的事实判断。"},{id:"gsc_necessary_fuxie",term:"复谐不馈",pinyin:"fù xié bù kuì",meaning:"疑难词组，有涉及复归和谐、不求馈养等解释。不能未经校定便将复谐立为人名，再解释成此人拒收礼物。"},{id:"gsc_necessary_tianhe",term:"同乎天和",pinyin:"tóng hū tiān hé",meaning:"与自然和合、不被毁誉夺其安顿。不是彻底失去情绪的医学状态，也不要求遭侮辱者必须保持无怒。"},{id:"gsc_necessary_chunu",term:"出怒不怒",pinyin:"chū nù bù nù",meaning:"发出怒而不以持续激愤为根，原文续说「则怒出于不怒矣」。怒与不怒的关系有不同句读和解释，不宣布任何自称自然的怒都正确。"},{id:"gsc_necessary_chuwei",term:"出为无为",pinyin:"chū wéi wú wéi",meaning:"发为而不以强作为根，原文续说「则为出于无为矣」。行动不必根于强作，但不宣布任何自称自然的为都正确。"},{id:"gsc_necessary_budeyi",term:"缘于不得已",pinyin:"yuán yú bù dé yǐ",meaning:"依循必要条件、不能任意妄加而行动。不得已既涉及不强作，也涉及情势中的必要，不只等同本能冲动或完全没有选择。"}];return(D,n)=>{const j=l("DaoReadingPrelude"),i=l("DaoTextReading"),r=l("DaoKeywordCards"),d=l("DaoLineGuide");return A(),C("div",null,[n[0]||(n[0]=s("",11)),e(j,{title:"先读前三段：从拒绝尊奉，到全形抱生与卫生之经",summary:"庚桑楚不愿将畏垒丰收据为个人功德，并激烈批评尊贤任知所引发的竞争；南荣趎听闻而未能相契，庚桑楚承认教化限度，转介老聃；老聃则从知仁义的两难与内外束缚，转向护卫生命的常道。",points:[{label:"先看",text:"庚桑楚为何不愿被列于贤人之间？丰收与个人功名之间有什么距离？"},{label:"再问",text:"听到耳中与落实于生命，有什么不同？教者为何可以承认自己不能继续化育？"},{label:"最后",text:"像婴儿、冰解冻释与祸福不至，应怎样理解，才不变成反学习或免灾承诺？"}],hint:"全篇九段均已整理：前三段立起名贤、思虑与教化的限度，四至六段转入宇泰定、道通其分与古人所知，末三段收在移是、四六之正与为与不得已；文末脉络逻辑链、三问解读、现代启发、关键词索引与核心句速查覆盖全篇。"}),n[1]||(n[1]=t("h2",{id:"一、庚桑楚居畏垒·不受尊奉与举贤任知",tabindex:"-1"},[a("一、庚桑楚居畏垒·不受尊奉与举贤任知 "),t("a",{class:"header-anchor",href:"#一、庚桑楚居畏垒·不受尊奉与举贤任知","aria-label":'Permalink to "一、庚桑楚居畏垒·不受尊奉与举贤任知"'},"​")],-1)),n[2]||(n[2]=t("h3",{id:"原文",tabindex:"-1"},[a("原文 "),t("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),e(i,{sections:g,glossary:p,"default-mode":"classic","aria-label":"庚桑楚·居畏垒与不受尊奉 原文"}),n[3]||(n[3]=t("blockquote",null,[t("p",null,[t("strong",null,"文字说明："),a("「偏得」「杓之人」「函车之兽」等不宜仅据现代常用字义解释。下文保留讨论空间，不将人物的激烈批评直接改成确定历史事实。")])],-1)),n[4]||(n[4]=t("h3",{id:"生僻字词",tabindex:"-1"},[a("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(r,{items:[{term:"庚桑楚",pinyin:["gēng","sāng","chǔ"],meaning:"篇中与老聃有关的人物，具体身世不在此坐实。"},{term:"画然知者",pinyin:["huà","rán","zhì","zhě"],meaning:"显露智识者，具体训释有差异。"},{term:"挈然仁者",pinyin:["qiè","rán","rén","zhě"],meaning:"显露仁行者，不直接证明其蓄意作伪。"},{term:"拥肿",pinyin:["yōng","zhǒng"],meaning:"朴拙、不显智巧等。"},{term:"鞅掌",pinyin:["yāng","zhǎng"],meaning:"不拘细节、劳作等，读音依注本统一。"},{term:"大壤",pinyin:["dà","rǎng"],meaning:"大丰收，壤常联系穰理解。"},{term:"俎豆",pinyin:["zǔ","dòu"],meaning:"祭器，此处联系祭祀尊奉。"},{term:"网罟",pinyin:["wǎng","gǔ"],meaning:"捕兽、捕鱼的网。"},{term:"深眇",pinyin:["shēn","miǎo"],meaning:"深远幽僻。"},{term:"栉",pinyin:["zhì"],meaning:"梳理。"},{term:"相轧",pinyin:["xiāng","yà"],meaning:"相互倾轧。"},{term:"阫",pinyin:["péi"],meaning:"墙，日中穴阫指白昼穿墙行盗。"}]}),n[5]||(n[5]=t("h3",{id:"核心句引读",tabindex:"-1"},[a("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(d,{title:"不把共同成效据为己功，也不把贤名变成争夺的标志",subtitle:"原文批评尊贤任知的力度，需要与丰收、拒绝祭祀的情境连读。",lines:[{text:"偏得老聃之道。",tone:"师承",guide:"偏的训释有差异，不能未经校定就定为独得精髓，再在第二段改说只得到一部分。可以先确认：庚桑楚与老聃之道有关，后续又承认自己的化育能力有限。对某种道理有所通达，与能帮助所有求问者，并不必然相同。"},{text:"画然知者去之……拥肿之与居，鞅掌之为使。",tone:"取舍",guide:"开篇确实以显智、显仁与朴拙相对，构成对智仁外显的批评。但不能直接证明朴拙者都无执著，也不能普遍断言有知识、有仁爱的人都应驱逐。需要留意的是：显能显德会怎样改变相处，而不是把无知立为新的用人资格。"},{text:"居三年，畏垒大壤。日计之而不足，岁计之而有余。",tone:"成效",guide:"三年后丰收，短时观察与全年尺度的评价不同。原文没有细述治理过程，因此不能断言完全没有行动。日计、岁计提醒读者不要只凭即时可见的举措衡量成效，也不保证任何少作为都会带来丰收。"},{text:"尸而祝之，社而稷之……南面而不释然。",tone:"尊奉",guide:"百姓不只感谢，而想以祭祀般的方式尊奉庚桑楚。不释然可联系他不愿被树立为贤者标表，不愿将自然与众人的成效归成个人功德。不能推成只要已有成效，就必然说明尚未无为；问题在成效如何被归属和利用。"},{text:"春气发而百草生……天道已行矣。",tone:"生成",guide:"春秋各得生成条件，百草、万宝由此生与成。庚桑楚借此松开单一功劳归属。岂无得而然哉不能直接改成春秋完全无所依待；自然运行并非毫无条件，而是不必另立一个自居功劳的主体。"},{text:"全其形生之人，藏其身也，不厌深眇。",tone:"处势",guide:"大兽离山、大鱼失水，都可能被较小力量所困，说明能力不能脱离适宜条件。藏身可联系避免暴露于尊奉与争夺，但不必要求每个人永久隐居，也不能说受害必定是因自己离道。"},{text:"举贤则民相轧，任知则民相盗。",tone:"竞争",guide:"这是对尊贤任知的直接、激烈批评，不能完全弱化成只反对炫耀。人物认为制度化的名位与利益会诱发倾轧欺盗。现代引申可检验评价与奖励如何改变行为，但不能由此直接否定所有能力选拔、教育和公平制度。"},{text:"大乱之本，必生于尧、舜之间……人相食。",tone:"极言",guide:"以圣王时代为乱源，颠倒常见的文明叙事，并将竞争逐利推到极端后果。应保留其批判力度，也应分清这是寓言论述，不是已经证实的千世因果预测。不能以一句并非反道德消除原文的尖锐性。"}]}),n[6]||(n[6]=s("",7)),e(i,{sections:o,glossary:c,"default-mode":"classic","aria-label":"庚桑楚·南荣趎问道 原文"}),n[7]||(n[7]=t("blockquote",null,[t("p",null,"**校勘说明：**来稿作「小足以化子」，与转介老子的情节不易相合。暂保留来稿并标注疑难，最终应依项目底本决定是否采用「不足以化子」等文字。")],-1)),n[8]||(n[8]=t("h3",{id:"生僻字词-1",tabindex:"-1"},[a("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-1","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(r,{items:[{term:"南荣趎",pinyin:["nán","róng","chú"],meaning:"篇中的求道人物。"},{term:"蹴然",pinyin:["cù","rán"],meaning:"肃然、惊动的样子。"},{term:"恶乎",pinyin:["wū","hū"],meaning:"在哪里、依托什么。"},{term:"营营",pinyin:["yíng","yíng"],meaning:"纷扰奔忙的样子。"},{term:"间之",pinyin:["jiàn","zhī"],meaning:"阻隔其间。"},{term:"达耳",pinyin:["dá","ěr"],meaning:"到达耳中，尚未落实或相契。"},{term:"藿蠋",pinyin:["huò","zhú"],meaning:"豆叶上的虫，属于古代昆虫认识。"},{term:"伏鹄卵",pinyin:["fú","hú","luǎn"],meaning:"伏卵、孵育大鸟之卵。"}]}),n[9]||(n[9]=t("h3",{id:"核心句引读-1",tabindex:"-1"},[a("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(d,{title:"听闻不等于落实，承认教化限度不等于否定学习",subtitle:"全形抱生包含生命照料，不应只剩抽象的内心修养。",lines:[{text:"全汝形，抱汝生，无使汝思虑营营。",tone:"保全",guide:"保全形体、抱守生命与减少纷扰思虑并列，不能预先排除身体保健，也不只是延长寿命。所反省的是奔逐耗损，不是所有思考。原文的三年是特定指引，不能当成照做三年必然得道的普遍保证。"},{text:"目之与形……耳之与形……心之与形。",tone:"隔阂",guide:"南荣趎借功能与形体并不自动一致，说明自己虽已听见却不能落实。此处盲、聋、狂是古代譬喻，不可据此把现实感官障碍或精神疾病归咎于失去本心、执念太多，也不能把这些状况当作修养失败。"},{text:"趎勉闻道达耳矣！",tone:"听闻",guide:"听到了指引，却仍未相契，是求问者诚实描述的困难。不能反过来说听闻完全无用，否则后续转往老子处问答也失去意义。关键在听懂语句与改变处身方式之间的距离。"},{text:"辞尽矣……其才固有巨小也。",tone:"教化",guide:"庚桑楚用不同生物的化育能力说明差异，承认继续说明未必能解决问题。古代蜂虫、鸡卵的认识不应当作现代生物事实。比喻重点在能力与所面对者是否相称，不是建立终身不可改变的才能等级。"},{text:"子胡不南见老子！",tone:"转介",guide:"不把自己维持为唯一答案来源，而让求问者寻求另一位老师。这是教化限度的具体处理，不需要贬低学习者，也不需要靠无限追加解释证明自己无所不能。偏得的训释尚有争议，不能单凭转介倒推他只懂一部分道。"}]}),n[10]||(n[10]=s("",8)),e(i,{sections:h,glossary:_,"default-mode":"classic","aria-label":"庚桑楚·南荣趎见老子 原文"}),n[11]||(n[11]=t("blockquote",null,[t("p",null,[t("strong",null,"文字说明："),a("「南荣囗」统一为「南荣趎」；「外韄」「内揵」「放道而行」「其病病者」等保留训释空间。卫生在此指护卫生命，不是现代医学或公共卫生术语。")])],-1)),n[12]||(n[12]=t("h3",{id:"生僻字词-2",tabindex:"-1"},[a("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-2","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(r,{items:[{term:"赢粮",pinyin:["yíng","liáng"],meaning:"携带粮食。"},{term:"偕",pinyin:["xié"],meaning:"一同。"},{term:"朱愚",pinyin:["zhū","yú"],meaning:"甚愚、大愚等。"},{term:"规规然",pinyin:["guī","guī","rán"],meaning:"拘谨、不自得的样子。"},{term:"洒濯",pinyin:["sǎ","zhuó"],meaning:"洗涤、清理，音义依注本统一。"},{term:"韄",pinyin:["huò"],meaning:"束缚。"},{term:"揵",pinyin:["jiàn"],meaning:"闭塞、固结等，读音训释有讨论空间。"},{term:"翛然",pinyin:["xiāo","rán"],meaning:"无拘无束的样子。"},{term:"侗然",pinyin:["tóng","rán"],meaning:"朴直、未显智巧的样子。"},{term:"嗌",pinyin:["yì"],meaning:"喉咙。"},{term:"嗄",pinyin:["shà"],meaning:"声音嘶哑。"},{term:"委蛇",pinyin:["wēi","yí"],meaning:"随顺变化。"},{term:"撄",pinyin:["yīng"],meaning:"扰动、纠缠。"},{term:"恶有人灾",pinyin:["wū","yǒu","rén","zāi"],meaning:"哪里还有人灾，恶读 wū。"}]}),n[13]||(n[13]=t("h3",{id:"核心句引读-2",tabindex:"-1"},[a("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(d,{title:"不要让解除束缚，反而成为另一种紧迫的自我要求",subtitle:"从三患到卫生之经，求问的方向逐步改变。",lines:[{text:"子何与人偕来之众也？",tone:"同行者",guide:"老子以许多人同行发问，南荣趎回头，随后才说出自己的知仁义忧患。可联系携带的判断、他人评价和内在纠葛理解，但原文未明确为每个虚拟同行者命名。忘答失问也不必解释成老子已经完成预定治疗。"},{text:"不知乎人谓我朱愚，知乎反愁我躯……",tone:"三患",guide:"南荣趎不是单纯想取消仁义，而是同时担忧他人的伤害与自身的耗损。三患的困难在两面都不能轻易舍弃。现代引申不应把打破框架改成不必顾及他人；他对害人、伤彼的关切正是问题的重要一面。"},{text:"今汝又言而信之。",tone:"印证",guide:"信可联系证实理解：现在的自述印证先前从神态所见。不能只译成你又相信自己的话。此处老子能从神态识人属于寓言描写，不提供现实中只看眉睫就可靠判断他人心理的技术。"},{text:"召其所好，去其所恶。十日自愁。",tone:"自整",guide:"南荣趎尝试整理自身，老子却指出仍有残留的纠结。召好去恶的所指、自愁的意义有不同解释，不必将全部经过化成压抑负面情绪的失败案例。也不能反说任何喜好、厌恶都必然有害。"},{text:"外韄者……内韄者……外内韄者。",tone:"束缚",guide:"外内拘束可能彼此加重，是可把握的方向。但将内揵、将外揵可能描述由纠缠产生的闭塞后果，不宜直接当作从内关上、从外关上的操作建议。原文疑难不能被替换成一套确定的自我控制流程。"},{text:"譬犹饮药以加病也。趎愿闻卫生之经。",tone:"改问",guide:"更多听闻没有帮助自己安顿，反而增加负担，南荣趎于是把问题转为怎样护卫生命。药病是譬喻，不意味着现实药物有害，也不证明求大道都错误。这里改变的是当下求问方式与需要。"},{text:"能抱一乎……能止乎！能已乎！",tone:"九问",guide:"一连串能否的提问涉及整合、停止强逐和转向自身，不必列成九级阶梯。无卜筮而知吉凶可以放在减少外求与妥善分辨的语境中，不能作为恢复预知未来能力的承诺。"},{text:"能舍诸人而求诸己乎！",tone:"求己",guide:"不把安顿完全交给他人的评价与保证，可以回看自己的处身方式。但求己不是不许求助、不许学习；南荣趎正是在另一位老师的帮助下继续问。自我反省与适当支持并不矛盾。"},{text:"能儿子乎！……和之至也。",tone:"婴儿",guide:"儿子在此指婴儿、幼儿，以未强作、未分裂的生命状态作譬喻。终日哭不哑、握而不掜、视而不瞬均是理想化描写，不是婴儿照护的生理指南。不能鼓励长时间哭泣、强握或不眨眼来求道。"},{text:"与物委蛇而同其波。",tone:"随顺",guide:"回应变化而不强定每一步，不能直接要求现实中迷失方向或放弃计划。随顺也不是向一切利害关系服从；后文正强调不以人物利害相撄。"},{text:"非也。是乃所谓冰解冻释者。",tone:"松动",guide:"老子明确区分初步解除束缚与所问的至人之德。南荣趎连续追问是否已经至极，使得到某种状态便急于确认完成的倾向继续受到检验。不宜机械画成婴儿、解冻、至人、超至人四级体系。"},{text:"交食乎地而交乐乎天。",tone:"共同生活",guide:"至人的描述仍包含共同生活，并非完全离开人世。地与天可联系生活所依和自然安顿，不按字面解释成地上吃饭、天上游乐。不会因不为怪、不为谋、不为事就取消所有合作与责任。"},{text:"祸亦不至，福亦不来。祸福无有，恶有人灾也！",tone:"祸福",guide:"结尾以强烈理想表达松开利害祸福的牵引。它不是现实免灾规律，不能说受害者必定因为仍有执念，也不能代替安全、医疗与法律保护。福也不来的表达，提醒不把修养仅作为求福避祸的工具。"}]}),n[14]||(n[14]=s("",41)),e(i,{sections:y,glossary:u,"default-mode":"classic","aria-label":"庚桑楚·宇泰定与灵台 原文"}),n[15]||(n[15]=t("blockquote",null,[t("p",null,"**整理说明：**本段开头「宇泰定者」至「谓之天子」，依据本次来稿后附引文补入；原文区从「学者」开始。最终合并时宜与统一底本核对。"),t("p",null,"「人见其人，物见其物」「与物穷者」「与物且者」等保留训释空间。末句不能被引申为外在灾害不存在、受害全由心造成。")],-1)),n[16]||(n[16]=t("h3",{id:"生僻字词-3",tabindex:"-1"},[a("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-3","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(r,{items:[{term:"宇泰定",pinyin:["yǔ","tài","dìng"],meaning:"心之居处、心胸安定。"},{term:"天光",pinyin:["tiān","guāng"],meaning:"自然的明照、通达，不是物理发光。"},{term:"天钧",pinyin:["tiān","jūn"],meaning:"自然的均平、运转或调均等。"},{term:"不虞",pinyin:["bù","yú"],meaning:"未料、不测之事。"},{term:"滑",pinyin:["gǔ"],meaning:"扰乱，滑成之滑常读 gǔ。"},{term:"灵台",pinyin:["líng","tái"],meaning:"心神之居处的譬喻。"},{term:"券",pinyin:["quàn"],meaning:"契券，借作契合、所凭之譬喻。"},{term:"期费",pinyin:["qī","fèi"],meaning:"预期报偿、向外求取等。"},{term:"贾人",pinyin:["gǔ","rén"],meaning:"商人，此处比喻以求偿为处世方向。"},{term:"跂",pinyin:["qì"],meaning:"企求、踮足而望等。"},{term:"镆铘",pinyin:["mò","yé"],meaning:"古代名剑。"}]}),n[17]||(n[17]=t("h3",{id:"核心句引读-3",tabindex:"-1"},[a("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(d,{title:"安定不等于无感，知止不等于放弃学习",subtitle:"既养护形体，又反省内心如何把变化变成持续的耗损。",lines:[{text:"宇泰定者，发乎天光。",tone:"安定",guide:"以心之安定与自然明照相接，强调通达不是刻意显示的光彩。人见其人、物见其物有不同解释，可以联系不以单一名位、用途遮住人与物，但不必把它改成某人能让所有真实自动显现的神秘能力。"},{text:"人有修者，乃今有恒。",tone:"修与恒",guide:"本段明确保留修与恒，不能因前文反智反贤就删除修养的作用。这里的修如何理解，仍须连同自然明照与不向外求名来看。人舍天助也不保证社会排斥必然证明一个人正确。"},{text:"知止乎其所不能知，至矣！",tone:"知止",guide:"学、行、辩都有条件与边界，不能以强求保证掌握全部。知止不是预先宣布任何未知永远不可研究，也不要求放弃具体能力的改善。它反省的是以有限认识自称无所不知，或用不相称的方法强取答案。"},{text:"备物将以形，藏不虞以生心，敬中以达彼。",tone:"照料",guide:"养形与保心并列，说明内在安顿并不排斥所需之物。藏不虞、敬中达彼的训释有空间，不能直接改成一套外物适量、关闭忧虑的心理操作。可以先保留妥善照料、谨慎应对与不被不测夺其根本的方向。"},{text:"若是而万恶至者，皆天也，而非人也。",tone:"不测",guide:"在已经妥善处身的前提下，仍可能遭遇不由自身决定的困厄，是本段重要的承认。天可联系自然条件、不可控际遇，不必定为人格化天的安排。也不能用这句把实际施害者的责任一概归给自然。"},{text:"不足以滑成，不可内于灵台。",tone:"不固藏",guide:"不让困厄扰乱安顿、占满心神，不等于否认事情发生或压抑所有感受。可以承认损失、处理后果，又不将其固定为全部自己。持续悲伤、恐惧并不证明一个人没有修养。"},{text:"灵台者有持，而不知其所持而不可持者也。",tone:"持而不执",guide:"有持、不知、不可持的并列形成张力，指向持守不能化为刻意抓取。具体主语、宾语关系有不同解释，不宜立即设定心握住一个无法命名的道实体。所持不能完全概念化，与毫无判断并非同义。"},{text:"不见其诚己而发，每发而不当。",tone:"察己",guide:"未明察自身实情便发动，容易失当。诚己不能只等于我主观觉得很真诚，因为真诚意图也可能产生错误。业入不舍、每更为失提醒困扰进入后若不松开，频繁改动也可能延续原有问题。"},{text:"为不善乎显明之中……为不善乎幽间之中……",tone:"不善",guide:"本段明确保留不善与惩诛，不能把前面的举贤任知批评解释成一切行为都无所谓。鬼神语言属于古代语境，可先理解为隐蔽不等于免除责任，不必当作现代事实证明。"},{text:"券内者，行乎无名；券外者，志乎期费。",tone:"求偿",guide:"以契券内外比喻向自身安顿与向外求取的差别。不必拟成与道或名利签订合同。贾人是交易求偿的比喻，不应扩成对所有商人、收入和正当报酬的否定。"},{text:"其身之不能容，焉能容人！",tone:"容身容人",guide:"与物穷、与物且的字义有争议，但容身与容人之间的关联值得保留。不宜断言孤独者都是太执著，或把所有人际困难归为内心没有空间。现实关系还受环境、资源与他人的行为影响。"},{text:"兵莫惨于志……非阴阳贼之，心则使之也。",tone:"志与心",guide:"以武器、贼寇极言志意与自然变化中的耗损，末句转向心如何参与。不能因此说寒暑、生死、疾病完全不会伤人，也不能从受害倒推受害者心有问题。此处可以反省额外的强求与对抗，不取消外在危险及防护。"}]}),n[18]||(n[18]=s("",9)),e(i,{sections:m,glossary:b,"default-mode":"classic","aria-label":"庚桑楚·道通其分与天门 原文"}),n[19]||(n[19]=t("blockquote",null,[t("p",null,[t("strong",null,"阅读说明："),a("「出而不反，见其鬼」「灭而有实」「以有形者象无形者而定」组成疑难语群。下文不将它们直接整理为“向外求名利便成鬼”的确定教义。")]),t("p",null,"「宇」「宙」可与空间、时间对读，但不等同现代科学定义。")],-1)),n[20]||(n[20]=t("h3",{id:"生僻字词-4",tabindex:"-1"},[a("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-4","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(r,{items:[{term:"分",pinyin:["fēn"],meaning:"区分、分化。"},{term:"备",pinyin:["bèi"],meaning:"具备、完备等，句法有讨论空间。"},{term:"反",pinyin:["fǎn"],meaning:"返回。"},{term:"象",pinyin:["xiàng"],meaning:"比拟、象征、指示等。"},{term:"窍",pinyin:["qiào"],meaning:"孔窍。"},{term:"本剽",pinyin:["běn","biāo"],meaning:"起端与末端等。"},{term:"宇",pinyin:["yǔ"],meaning:"关联广延、空间，不只是一件有形实体。"},{term:"宙",pinyin:["zhòu"],meaning:"关联延续、时间。"},{term:"天门",pinyin:["tiān","mén"],meaning:"生成出入之门的譬喻。"},{term:"无有",pinyin:["wú","yǒu"],meaning:"生成根本不被一件既有之物穷尽的表达。"}]}),n[21]||(n[21]=t("h3",{id:"核心句引读-4",tabindex:"-1"},[a("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-4","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(d,{title:"分别可以说明事物，却不能凭分别穷尽生成根本",subtitle:"无有不是可以重新占有的一件特殊物。",lines:[{text:"道通其分也，其成也毁也。",tone:"分与通",guide:"道贯通区分，某种形态成立也涉及其他形态的改变、解除。与《齐物论》的分成毁相通，但不等于现实建成与破坏在价值和后果上毫无区别。相通不需要抹掉具体差别。"},{text:"所恶乎分者，其分也以备。",tone:"求备",guide:"分与备的关系涉及以分别求完备、以有限所备作为凭借等解释。可以反省想靠分类掌握全部的期待，但不能宣称一切分类、计划和准备都有害；上一段刚提出备物养形。"},{text:"出而不反，见其鬼。出而得，是谓得死。",tone:"疑难",guide:"出、反、得、死、鬼的关系不能只按来稿引申作向外求名利、离道成鬼。可以联系向外而不返、所得的有限与形态消亡理解，同时保留古代鬼生死语境。没有明确列出的名利对象，不宜补成唯一所指。"},{text:"以有形者象无形者而定矣！",tone:"比拟",guide:"以有形说明无形，是论说必须面对的方法问题。定既可能涉及据以定说，也有其他解释，不能只认定这是已经获准的安顿方法。譬喻可以指引，却不能把无形根本变成与譬喻完全相同的物。"},{text:"有实而无乎处者，宇也；有长而无本剽者，宙也。",tone:"宇宙",guide:"以无固定处所的广延、无可指定始末的延续说明宇宙。可与空间时间对读，但不能由无处直接推出已证明空间无限，由无本剽推出已证明时间永无起点。古代哲学表达与现代物理问题需要分开。"},{text:"入出而无见其形，是谓天门。",tone:"天门",guide:"生死、出入可见，所由之门却不是一个能直接指认的形体。天门是生成根本的譬喻，不是实际隐藏门户，也不是神秘体验的可靠检验标准。"},{text:"有不能以有为有，必出乎无有。",tone:"生成",guide:"一件已经存在的物不能被直接认作一切存在的充分根本。无有使生成问题不止于追问更早的一件物，但不必设成绝对虚无或一种特殊材料。原文的有与无有也不能直接套成现代宇宙起源模型。"},{text:"而无有一无有。圣人藏乎是。",tone:"安顿",guide:"无有也不能立即成为新的区分与据执对象，一的具体句法仍有空间。圣人藏乎是可与篇首拒绝显为贤者呼应：不将自己固定在某个名位和所得中。藏不只指地理隐居，也不等于远离一切生命活动。"}]}),n[22]||(n[22]=s("",18)),e(i,{sections:x,glossary:q,"default-mode":"classic","aria-label":"庚桑楚·古人之知与三种理解 原文"}),n[23]||(n[23]=t("blockquote",null,[t("p",null,"**阅读说明：**原文两次使用「其次」，确有比较层次；但末尾又说「公族」「非一」，同时保留相近与差异。不要将这三种说法推广为全篇所有人物的固定等级。"),t("p",null,"「昭景也，著戴也；甲氏也，著封也」涉及古代族氏譬喻，细节宜依注本校定。")],-1)),n[24]||(n[24]=t("h3",{id:"生僻字词-5",tabindex:"-1"},[a("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-5","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(r,{items:[{term:"恶乎至",pinyin:["wū","hū","zhì"],meaning:"达到了哪里、何种程度。"},{term:"未始",pinyin:["wèi","shǐ"],meaning:"未曾开始、未曾。"},{term:"丧",pinyin:["sàng"],meaning:"丧失，以生为丧。"},{term:"反",pinyin:["fǎn"],meaning:"返回，以死为反。"},{term:"俄",pinyin:["é"],meaning:"不久、很快。"},{term:"尻",pinyin:["kāo"],meaning:"臀部、身体后部。"},{term:"公族",pinyin:["gōng","zú"],meaning:"同属一族的譬喻。"},{term:"非一",pinyin:["fēi","yī"],meaning:"并非完全同一，不应省略差异。"}]}),n[25]||(n[25]=t("h3",{id:"核心句引读-5",tabindex:"-1"},[a("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-5","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(d,{title:"相通不等于完全相同，最高评价也不必成为否定现实的口号",subtitle:"三种说法既有比较，也仍被比作同族。",lines:[{text:"有以为未始有物者，至矣，尽矣，弗可以加矣！",tone:"未始有物",guide:"原文给予这类认识最高评价，涉及不先以物的分别确立根本。不能直接推成眼前物体全不存在，更不能补成只有一个名叫道的实体独自存在。与《齐物论》同类表达对读，可把握对固定分别的反省。"},{text:"将以生为丧也，以死为反也，是以分已。",tone:"次一层",guide:"已经承认有物，再将生判为丧失、死判为返回，仍形成分别。原文将其列为其次，所以不能单独摘取生为丧、死为反，作为全篇劝人求死的最终教义。它反而提示：倒转通常的生死评价，仍可能保留评价框架。"},{text:"以无有为首，以生为体，以死为尻。",tone:"身体譬喻",guide:"无有、生、死被连成身体的首、体与后部。它既有先后叙述，也以身体譬喻提示相通，不能只归成第三层分别更细、所以全无价值。后面的愿与之为友，仍肯定能理解其一体关系者。"},{text:"孰知有无死生之一守者，吾与之为友。",tone:"相通",guide:"理解有无死生相通，而不只执持一端，是本段择友表达。相通不等于个体意识永存，也不取消现实生死的后果。第一人称是篇中论说声音，不必立刻当作历史庄子的实际交友名单。"},{text:"是三者虽异，公族也……非一也。",tone:"同族非一",guide:"同族说明相关，非一说明不完全相同。不能只留下名字不同但同根，从而删掉原文对差异的强调。族氏细节尚有争议，可先把握三种认识彼此相关而又不能互相替代。"}]}),n[26]||(n[26]=s("",28)),e(i,{sections:f,glossary:k,"default-mode":"classic","aria-label":"庚桑楚·移是与名实 原文"}),n[27]||(n[27]=t("blockquote",null,[t("p",null,[t("strong",null,"阅读说明："),a("「有生黬」「移是」「腊者之有膍胲」「又适其偃」均有训释问题。保留来稿文字，不将「移是」直接定为执著是非，也不将这一段未经说明便归给老子发言。")])],-1)),n[28]||(n[28]=t("h3",{id:"生僻字词-6",tabindex:"-1"},[a("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-6","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(r,{items:[{term:"黬",pinyin:["yǎn"],meaning:"黑斑、黑点等，整句解释有争议。"},{term:"移是",pinyin:["yí","shì"],meaning:"转移所是、推移所执等，不只等于执著。"},{term:"腊",pinyin:["xī"],meaning:"此处有干肉、干制兽体的解释，不必作腊祭。"},{term:"膍胲",pinyin:["pí","gǎi"],meaning:"胃肠、足部或体内组织等，宜依注本校定。"},{term:"质",pinyin:["zhì"],meaning:"质押、保证，以己为质涉及自身。"},{term:"偿节",pinyin:["cháng","jié"],meaning:"偿付、维护所立之节。"},{term:"彻",pinyin:["chè"],meaning:"通达、显达等。"},{term:"蜩",pinyin:["tiáo"],meaning:"蝉，借《逍遥游》形象作比。"}]}),n[29]||(n[29]=t("h3",{id:"核心句引读-6",tabindex:"-1"},[a("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-6","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(d,{title:"以生为本，却可能以自身偿付已经树立的名节",subtitle:"批评的焦点不只是有无知识，而是生命如何被既定尺度支配。",lines:[{text:"尝言移是，非所言也。虽然，不可知者也。",tone:"疑难",guide:"开头即提示所言与所知的限度，移是本身又有多种训释。不能由一个现代解释将整段固定成是非皆无意义。后文仍可辨出较明确的问题：名实、质押与所立节操如何牵动生命。"},{text:"腊者之有膍胲，可散而不可散也。",tone:"部分与整体",guide:"体内部分可以区分，又不能脱离整体任意处理，是一种可保留的阅读方向。腊不必作腊祭，膍胲也不能未经校定便指定为祭祀用牛胃和脚。比喻细节有争议，不应据此完成一套固定的整体主义理论。"},{text:"以生为本，以知为师，因以乘是非。",tone:"尺度",guide:"以生为根本，以知作为指导，继而据是非处身。这些词并非单独出现就全然错误；全篇也曾要求抱汝生、知止。问题需沿后文看：是否将有限判断变成必须维护的名实身份。"},{text:"因以己为质……因以死偿节。",tone:"反转",guide:"从以生为本到以死偿节，形成尖锐反转：自身被质押给所立名节，维护名实的要求反过来压倒生命。不能将其扩成所有承诺、责任都应放弃，也不能说任何持守最终必然导致死亡。"},{text:"以用为知，以不用为愚；以彻为名，以穷为辱。",tone:"评价",guide:"只依能被取用、显达与受困评价知愚荣辱，容易将外在结果当作完整人格。与《人间世》无用问题对读，不等于把方向机械倒转成凡无用者都优于有用者。可反省的是单一尺度的支配。"},{text:"是蜩与学鸠同于同也。",tone:"局限",guide:"借《逍遥游》的形象指出一类相近局限。不能补成蜩与学鸠自以为彼此不同，也不应因称其小知便否定其具体生活能力。所批评的是把局部经验当作全部尺度。"}]}),n[30]||(n[30]=s("",9)),e(i,{sections:z,glossary:w,"default-mode":"classic","aria-label":"庚桑楚·五至与四六 原文"}),n[31]||(n[31]=t("blockquote",null,[t("p",null,[t("strong",null,"释义说明："),a("「放骜」不能直接按现代字面译为傲慢道歉。「四六」是四组六项，不意味着志、心、德、道已经被划成四层实体结构。")])],-1)),n[32]||(n[32]=t("h3",{id:"生僻字词-7",tabindex:"-1"},[a("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-7","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(r,{items:[{term:"蹍",pinyin:["niǎn"],meaning:"踩、践踏。"},{term:"放骜",pinyin:["fàng","ào"],meaning:"传统有恭敬、逊谢等解释，不径直作傲慢解。"},{term:"妪",pinyin:["yù"],meaning:"亲和抚慰，音读依注本统一。"},{term:"辟金",pinyin:["pì","jīn"],meaning:"不依外在凭证等，有不同解释。"},{term:"勃",pinyin:["bó"],meaning:"悖乱、激荡等。"},{term:"谬",pinyin:["miù"],meaning:"错乱，也可联系缪、缠绕理解。"},{term:"累",pinyin:["lěi"],meaning:"负累、牵累。"},{term:"塞",pinyin:["sè"],meaning:"阻塞。"},{term:"荡",pinyin:["dàng"],meaning:"扰动、激荡。"}]}),n[33]||(n[33]=t("h3",{id:"核心句引读-7",tabindex:"-1"},[a("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-7","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(d,{title:"形式不是相处的全部，解除扰动也不等于消灭情绪与能力",subtitle:"原文以不荡胸中为条件，不应改成二十四项活动一概禁绝。",lines:[{text:"蹍市人之足，则辞以放骜，兄则以妪，大亲则已矣。",tone:"亲疏与辞谢",guide:"不同亲疏关系中的辞谢方式不同，说明真正相亲未必需要同样的外在程序。放骜不宜译成傲慢道歉；对至亲已矣也不能推广为亲人受伤无需道歉或照料。形式减少，不等于责任消失。"},{text:"至礼有不人，至义不物，至知不谋，至仁无亲，至信辟金。",tone:"五至",guide:"五个至以反常表述限制通常形式，具体词义仍有讨论空间。可以关注礼、义、知、仁、信不能只靠外在标志保证，却不能把所有人我区分、计划、亲近和凭证都取消。至信尤其不应变成现实交易不保留记录的建议。"},{text:"彻志之勃，解心之谬，去德之累，达道之塞。",tone:"解除",guide:"彻、解、去、达共同指向解除悖乱、缠绕、牵累与阻塞。不是把志、心、德、道本身去掉，也不必把四者排列成最外至最内的固定层级。四种说法可以相互照明，而非空间结构。"},{text:"恶欲喜怒哀乐六者，累德也。",tone:"情绪",guide:"原文确实对情欲牵累提出尖锐批评，不能完全改成中性情绪说明。但下一句说不荡胸中，故不宜要求消灭一切感受。《知北游》篇末还承认哀乐来去，情绪出现不必自动证明修养失败。"},{text:"去就取与知能六者，塞道也。",tone:"活动与拘塞",guide:"离去、趋就、取、给予、知、能都是生活活动，不能只凭列入四六便全部禁止。全篇仍有学习、转介、养形与实际应接。需要辨明活动是否被强求、身份或得失要求占满。"},{text:"正则静，静则明，明则虚。",tone:"递进",guide:"原文给出正、静、明、虚的递进关系，可以作为整体阅读线索。不是可机械重复的五级心理疗程，也不保证安静后所有判断自动正确。明与虚相接，恰提醒明白不能立即成为新的自满据执。"},{text:"虚则无为而无不为也。",tone:"行动",guide:"虚不只指空无，更可联系不被已有要求塞满。无为与无不为相接，不能译成没有什么不能做的全能保证。末段进一步谈有为欲当，说明问题仍是如何恰当地行动，而非永不行动。"}]}),n[34]||(n[34]=s("",16)),e(i,{sections:P,glossary:T,"default-mode":"classic","aria-label":"庚桑楚·为与不得已 原文"}),n[35]||(n[35]=t("blockquote",null,[t("p",null,[t("strong",null,"阅读说明："),a("「德之钦」「动无非我」「俍乎人」「全人恶天」「介者拸画」「复谐不馈」均有训释空间。")]),t("p",null,"不将道、德、生、性画成已确定的时间生成流程，也不把所有人物列成固定高下阶梯。")],-1)),n[36]||(n[36]=t("h3",{id:"生僻字词-8",tabindex:"-1"},[a("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-8","aria-label":'Permalink to "生僻字词"'},"​")],-1)),e(r,{items:[{term:"钦",pinyin:["qīn"],meaning:"尊、所尊奉等，亦有其他解释。"},{term:"谟",pinyin:["mó"],meaning:"谋议、思量。"},{term:"睨",pinyin:["nì"],meaning:"斜视，句中具体比喻关系有讨论空间。"},{term:"中微",pinyin:["zhòng","wēi"],meaning:"射中细微目标，中读 zhòng。"},{term:"俍",pinyin:["liáng"],meaning:"善、工巧等，音义宜依注本统一。"},{term:"恶天",pinyin:["wū","tiān"],meaning:"有疑问用法解释，不径直作厌恶天道。"},{term:"胞人",pinyin:["páo","rén"],meaning:"联系庖人、厨役理解。"},{term:"胥靡",pinyin:["xū","mí"],meaning:"被拘系、服劳役者。"},{term:"天和",pinyin:["tiān","hé"],meaning:"自然和合的安顿。"},{term:"不得已",pinyin:["bù","dé","yǐ"],meaning:"受必要条件限制而不妄加，不只是主观自发。"}]}),n[37]||(n[37]=t("h3",{id:"核心句引读-8",tabindex:"-1"},[a("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-8","aria-label":'Permalink to "核心句引读"'},"​")],-1)),e(d,{title:"为不必出于强作，必要回应也不能以自然之名免除检验",subtitle:"篇末以有为欲当收束，仍然关心行动是否恰当。",lines:[{text:"道者，德之钦也；生者，德之光也；性者，生之质也。",tone:"关系",guide:"原文说明道、德、生、性的关联，钦、光、质是不同关系词。不能全部替换成前者先制造后者的时间因果，更不能由此断言形成完整宇宙生成图。"},{text:"性之动谓之为，为之伪谓之失。",tone:"为与失",guide:"性之活动称为为，说明行动本身并非错误。伪涉及造作、加工、伪饰等，不能只作蓄意撒谎。自然与人为的界限也不等于冲动与计划：周密准备可能必要，未经考虑的自发行为也可能伤人。"},{text:"知者，接也；知者，谟也。",tone:"知",guide:"接触、应接与思量谋议都进入知的讨论，不能简化成被动感官和主动计划两种完全外在的低级知。所不知提醒认识有范围，与第四段知止相接，不必取消具体判断和学习。"},{text:"动以不得已之谓德，动无非我之谓治。",tone:"必要与自身",guide:"依必要而动与不违自身的动，需要结合名相反而实相顺理解。不得已不只等于完全没有选择，无非我也不是凡我愿意便合理。较稳妥的是辨明回应是否由实际条件要求，而非靠强作、自证身份不断加码。"},{text:"羿工乎中微而拙乎使人无己誉。",tone:"能力与声誉",guide:"技艺精细不等于能够控制他人如何评价自己，呼应庚桑楚面对尊奉而不安。不能由赞誉存在倒推修养不足，也不必要求人把所有能力藏到不可见。区别在于成果与外界评价并不完全由同一人掌握。"},{text:"工乎天而俍乎人者，唯全人能之。",tone:"天与人",guide:"本段将天、人并置，反省偏于一端的工与拙。俍的解释及上下句关系仍需校定，不把天简化成神秘知识、人简化成社交技巧，也不据此建立全人高于一切圣人的通用等级。"},{text:"全人恶天，恶人之天。",tone:"不强分",guide:"恶有何、哪里等疑问解释，句意可能涉及何必再强分天与人。不能仅按厌恶来补成全人反对刻意彰显天道。关键是承认疑难，不让引申替代原文。"},{text:"非以其所好笼之而可得者，无有也。",tone:"所好与笼",guide:"所好可能成为被牵引、笼取的入口，是本段鲜明警告。但伊尹、百里奚的心理不能凭故事补写；喜好本身也不等于一切束缚。可以反省人是否利用他人的愿望控制其选择，不把这种描述变成操纵指南。"},{text:"介者拸画……夫复谐不馈而忘人。",tone:"忘与放下",guide:"刑者、劳役者的譬喻涉及毁誉、死生之忘，不能据此称受刑为得道捷径。复谐不馈是疑难词组，不径直立为第三个人物。忘人也不等于遗弃他人、拒绝帮助，而可联系不被人为评判占满。"},{text:"敬之而不喜，侮之而不怒。",tone:"毁誉",guide:"强调不被敬侮夺其安顿，不必译成完全没有感受。遭侮辱而愤怒不自动证明失败，维护界限、求助与追究责任仍然可以必要。下一句又谈出怒，不能把天和定为怒从此绝不出现。"},{text:"出怒不怒……出为无为。",tone:"回应",guide:"反常表述可联系怒不根于持续激愤、为不根于强作。句法仍有不同解释，不机械画成内在根与外在枝叶，更不应让行为者自称这是天和之怒就免除对伤害的判断。"},{text:"有为也欲当，则缘于不得已。",tone:"恰当",guide:"篇末明确谈有为是否当，保留了行动的相称性问题。不得已可以限制妄加、减少为名为利的多余动作，但不能成为我没有办法的免责口号。必要性还须联系条件、替代方案、后果和他人权益辨析。"}]}),n[38]||(n[38]=s("",138))])}}});export{N as __pageData,R as default};
